{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "A close kinase-inhibitor analogue sharing the piperazine-pyrimidine-aniline core and basic piperazine (brigatinib) has an absolute oral bioavailability of 46% in healthy volunteers, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The same scaffold analogue in fasted healthy volunteers showed 57% absolute oral bioavailability, demonstrating that the ionizable piperazine and high TPSA do not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Brepocitinib, a structurally distinct heteroaromatic kinase inhibitor, had 75% absolute oral bioavailability in humans, providing broader evidence that moderately large, polar kinase inhibitors can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Trametinib, another orally administered kinase inhibitor with high molecular weight and multiple hydrogen-bond acceptors, showed 72% oral bioavailability in fasting patients, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Although the physicochemical prior is unfavorable, the closest experimental analogues with the same piperazine-pyrimidine-aniline kinase-inhibitor scaffold have absolute oral bioavailability of 46-77% in humans, and all provided experimental records report F >= 20%. The query is therefore predicted to have high oral bioavailability (F >= 20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query itself is included in the provided evidence.",
    "No low-bioavailability analogue with the same scaffold was provided to challenge the high prediction.",
    "Food effect, formulation, and efflux/metabolism contributions for the query are not directly measured."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C06", "C05", "C17"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "piperazine-pyrimidine-aniline kinase inhibitors"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C10", "C11", "C09", "C08", "C01", "C16"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "other oral drugs with measured high bioavailability"
    }
  ],
  "revision_action": "initial"
}

